SELECT rr.id, rr.reviewer_id as reviewerId, a.name as reviewerName, rr.blog_id as blogId, b.title as blogTitle, rr.user_id as userId, u.username, rr.comment_id as commentId, c.content as commentContent, rr.review_time as reviewTime, rr.review_result as reviewResult, rr.review_reason as reviewReason, rr.message_to_author as messageToAuthor, rr.review_type as reviewType FROM review_record rr LEFT JOIN admin a ON rr.reviewer_id = a.id LEFT JOIN blog b ON rr.blog_id = b.id LEFT JOIN user u ON rr.user_id = u.id LEFT JOIN comment c ON rr.comment_id = c.id
AND rr.reviewer_id = #{reviewerId}
AND rr.review_type = #{reviewType}
AND rr.review_result = #{reviewResult}
AND rr.review_time >= #{beginTime}
AND rr.review_time <= #{endTime}
AND rr.user_id = #{userId}
AND rr.blog_id = #{blogId}
AND rr.comment_id = #{commentId}
ORDER BY rr.review_time DESC

